#include <string>

class Solution {
public:
    std::string freqAlphabets(std::string s) {
        std::string res = "";
        int n = s.size();
        int i = 0;
        while (i < n) {
            if (i + 2 < n && s[i + 2] == '#') {
                int val = std::stoi(s.substr(i, 2));
                res += (char)('a' + val - 1);
                i += 3;
            } else {
                int val = s[i] - '0';
                res += (char)('a' + val - 1);
                i += 1;
            }
        }
        return res;
    }
};

class Solution {
    public String freqAlphabets(String s) {
        StringBuilder res = new StringBuilder();
        int n = s.length();
        int i = 0;
        while (i < n) {
            if (i + 2 < n && s.charAt(i + 2) == '#') {
                int val = Integer.parseInt(s.substring(i, i + 2));
                res.append((char)('a' + val - 1));
                i += 3;
            } else {
                int val = s.charAt(i) - '0';
                res.append((char)('a' + val - 1));
                i += 1;
            }
        }
        return res.toString();
    }
}

var freqAlphabets = function(s) {
    let res = "";
    const n = s.length;
    let i = 0;
    while (i < n) {
        if (i + 2 < n && s[i + 2] === "#") {
            const val = parseInt(s.slice(i, i + 2), 10);
            res += String.fromCharCode(97 + val - 1);
            i += 3;
        } else {
            const val = s.charCodeAt(i) - 48;
            res += String.fromCharCode(97 + val - 1);
            i += 1;
        }
    }
    return res;
